1	// Helpers that reproduce CPython repr() formatting for strings and integers.
2	
3	// CPython prefers single quotes; if the string contains a single quote but no
4	// double quote, it switches to double quotes. Backslash, newline, carriage
5	// return and tab are escaped.
6	export function pyStr(s) {
7	  const hasSingle = s.includes("'");
8	  const hasDouble = s.includes('"');
9	  const quote = hasSingle && !hasDouble ? '"' : "'";
10	  let out = '';
11	  for (const ch of s) {
12	    if (ch === '\\') out += '\\\\';
13	    else if (ch === '\n') out += '\\n';
14	    else if (ch === '\r') out += '\\r';
15	    else if (ch === '\t') out += '\\t';
16	    else if (ch === quote) out += '\\' + ch;
17	    else out += ch;
18	  }
19	  return quote + out + quote;
20	}
21	
22	// Python repr of a value: strings use pyStr; finite integers use plain
23	// decimal notation.
24	export function pyValue(v) {
25	  if (typeof v === 'string') return pyStr(v);
26	  return String(v);
27	}

