3	export class ValueDuplicationError extends Error {
4	  constructor(value) {
5	    super(`ValueDuplicationError: ${value}`);
6	    this.name = 'ValueDuplicationError';
7	    this.value = value;
8	  }
9	}
10	
11	export class KeyError extends Error {
12	  constructor(key) {
13	    super(`KeyError: ${key}`);
14	    this.name = 'KeyError';
15	    this.key = key;
16	  }
17	}
