19	export class Bidict {
20	  constructor(pairs) {
21	    // Insertion-ordered entries: [key, value]. Duplicate keys keep the
22	    // first position but take the last value, like a Python dict.
23	    this.entries = [];
24	    this.index = Object.create(null);
25	    for (const [key, value] of pairs) {
26	      const id = String(key);
27	      if (Object.prototype.hasOwnProperty.call(this.index, id)) {
28	        this.entries[this.index[id]][1] = value;
29	      } else {
30	        this.index[id] = this.entries.length;
31	        this.entries.push([key, value]);
32	      }
33	    }
34	    // A bidict rejects duplicate values.
35	    const seen = new Set();
36	    for (const [, value] of this.entries) {
37	      if (seen.has(value)) {
38	        throw new ValueDuplicationError(value);
39	      }
40	      seen.add(value);
41	    }
42	  }
43	
44	  copy() {
45	    return new Bidict(this.entries.map(([key, value]) => [key, value]));
46	  }
47	
48	  set(key, value) {
49	    const id = String(key);
50	    if (Object.prototype.hasOwnProperty.call(this.index, id)) {
51	      const entry = this.entries[this.index[id]];
52	      if (entry[1] === value) {
53	        return;
54	      }
55	      for (const [otherKey, otherValue] of this.entries) {
56	        if (otherKey !== key && otherValue === value) {
57	          throw new ValueDuplicationError(value);
58	        }
59	      }
60	      entry[1] = value;
61	    } else {
62	      for (const [, otherValue] of this.entries) {
63	        if (otherValue === value) {
64	          throw new ValueDuplicationError(value);
65	        }
66	      }
67	      this.index[id] = this.entries.length;
68	      this.entries.push([key, value]);
69	    }
70	  }
71	
72	  invGet(value) {
73	    for (const [key, entryValue] of this.entries) {
74	      if (entryValue === value) {
75	        return key;
76	      }
77	    }
78	    throw new KeyError(value);
79	  }
80	
81	  toString() {
82	    const body = this.entries
83	      .map(([key, value]) => `${pyValue(key)}: ${pyValue(value)}`)
84	      .join(', ');
85	    return `bidict({${body}})`;
86	  }
87	}

1	// Minimal argparse-style CLI parser (ESM, zero dependencies).
2	// Mirrors the verified behavior of the original script's argument handling:
3	// usage/errors on stderr with exit code 2, -h/--help on stdout with exit 0.
4	
5	import { pyStr } from './pyrepr.mjs';
6	
7	const SPECS = [
8	  { flag: '--k1', dest: 'k1', metavar: 'K1', type: 'str' },
9	  { flag: '--v1', dest: 'v1', metavar: 'V1', type: 'int' },
10	  { flag: '--k2', dest: 'k2', metavar: 'K2', type: 'str' },
11	  { flag: '--v2', dest: 'v2', metavar: 'V2', type: 'int' },
12	];
13	
14	const BY_FLAG = {};
15	for (const spec of SPECS) BY_FLAG[spec.flag] = spec;
16	
17	function usageLine(prog) {
18	  return `usage: ${prog} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2`;
19	}
20	
21	function fail(prog, message) {
22	  process.stderr.write(usageLine(prog) + '\n');
23	  process.stderr.write(`${prog}: error: ${message}\n`);
24	  process.exit(2);
25	}
26	
27	function printHelp(prog) {
28	  const lines = [
29	    usageLine(prog),
30	    '',
31	    'options:',
32	    '  -h, --help  show this help message and exit',
33	  ];
34	  for (const spec of SPECS) {
35	    lines.push(`  ${spec.flag} ${spec.metavar}`);
36	  }
37	  process.stdout.write(lines.join('\n') + '\n');
38	  process.exit(0);
39	}
