41	// Accepts an optional sign followed by digits only, with surrounding
42	// whitespace allowed; anything else is rejected as an invalid int value.
43	function parseIntValue(raw, flag, prog) {
44	  const trimmed = raw.trim();
45	  if (!/^[+-]?[0-9]+$/.test(trimmed)) {
46	    fail(prog, `argument ${flag}: invalid int value: ${pyStr(raw)}`);
47	  }
48	  return parseInt(trimmed, 10);
49	}
