51	export function parseArgs(argv, prog) {
52	  const result = {};
53	  const extras = [];
54	
55	  let i = 0;
56	  while (i < argv.length) {
57	    const token = argv[i];
58	
59	    if (token === '-h' || token === '--help') {
60	      printHelp(prog);
61	    }
62	
63	    let flag = token;
64	    let inlineValue = null;
65	    const eq = token.indexOf('=');
66	    if (token.startsWith('--') && eq !== -1) {
67	      flag = token.slice(0, eq);
68	      inlineValue = token.slice(eq + 1);
69	    }
70	
71	    const spec = BY_FLAG[flag];
72	    if (!spec) {
73	      extras.push(token);
74	      i += 1;
75	      continue;
76	    }
77	
78	    let rawValue;
79	    if (inlineValue !== null) {
80	      rawValue = inlineValue;
81	      i += 1;
82	    } else {
83	      if (i + 1 >= argv.length) {
84	        fail(prog, `argument ${spec.flag}: expected one argument`);
85	      }
86	      rawValue = argv[i + 1];
87	      i += 2;
88	    }
89	
90	    result[spec.dest] =
91	      spec.type === 'int' ? parseIntValue(rawValue, spec.flag, prog) : rawValue;
92	  }
93	
94	  const missing = SPECS.filter((spec) => !(spec.dest in result)).map(
95	    (spec) => spec.flag
96	  );
97	  if (missing.length > 0) {
98	    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
99	  }
100	
101	  if (extras.length > 0) {
102	    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
103	  }
104	
105	  return { k1: result.k1, v1: result.v1, k2: result.k2, v2: result.v2 };
106	}

